from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        prefix = []
        total = 0

        for s in skill:
            total += s
            prefix.append(total)

        start = 0
        n = len(skill)

        for j in range(1, len(mana)):
            prev_mana = mana[j - 1]
            curr_mana = mana[j]

            wait = prev_mana * prefix[0]

            for i in range(1, n):
                wait = max(
                    wait,
                    prev_mana * prefix[i] - curr_mana * prefix[i - 1]
                )

            start += wait

        return start + mana[-1] * prefix[-1]
